"""Scoped live UX patch. Keeps concurrent navigation and SDK changes."""
from pathlib import Path
import shutil,datetime
root=Path('/opt/agent-vault')
backup=Path('/var/backups/agent-vault')/(datetime.datetime.now().strftime('%Y%m%d-%H%M%S')+'-ux-pass')
backup.mkdir(parents=True)
def edit(rel,fn):
 p=root/rel
 old=p.read_text(); new=fn(old)
 if old!=new:
  dest=backup/rel;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest);p.write_text(new)

JS="\nconst names={reading:'阅读档案',video:'视频频道',books:'深度读书',digest:'建造者观察',html:'思考与作品',seminar:'研讨沉淀'};\nconst platforms={douyin:'抖音',weixin_channels:'视频号',bilibili:'B站',youtube:'YouTube',wechat:'微信',weixin:'微信'};\nconst $=s=>document.querySelector(s), params=new URLSearchParams(location.search);\nlet rows=[],selected=names[params.get('type')]?params.get('type'):'';\n$('#search').value=params.get('q')||'';\nfunction node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}\nfunction state(){const u=new URL(location.href);selected?u.searchParams.set('type',selected):u.searchParams.delete('type');const q=$('#search').value.trim();q?u.searchParams.set('q',q):u.searchParams.delete('q');history.replaceState(null,'',u)}\nfunction filters(){ $('#filters').replaceChildren(...[['','全部'],...Object.entries(names)].map(([key,label])=>{const b=node('button',label+' '+rows.filter(x=>!key||x.collection===key).length);b.type='button';b.classList.toggle('active',selected===key);b.setAttribute('aria-pressed',String(selected===key));b.onclick=()=>{selected=key;state();filters();render()};return b}));}\nfunction render(){const q=$('#search').value.trim().toLowerCase();const found=rows.filter(x=>(!selected||x.collection===selected)&&[x.title,x.summary,x.source_account,platforms[x.source_platform],...(x.tags||[])].join(' ').toLowerCase().includes(q));$('#count').textContent=(selected?names[selected]:'全部内容')+' · '+found.length+' / '+rows.length+' 份';$('#empty').hidden=!!found.length;$('#clear').hidden=!q&&!selected;$('#cards').replaceChildren(...found.map(x=>{const card=node('article',undefined,'vault-tile'),c=node('div',undefined,'tile-content'),top=node('div',undefined,'tile-top');top.append(node('span',names[x.collection]||'档案','tile-type'),node('time',x.date||'长期档案'));const h=node('h2'),a=node('a',x.title);a.href=x.url;h.append(a);c.append(top,h);if(x.source_platform&&x.source_platform!=='unknown')c.append(node('p',[platforms[x.source_platform]||x.source_platform,x.source_account].filter(Boolean).join(' · '),'tile-source'));if(x.summary)c.append(node('p',x.summary.slice(0,230)+(x.summary.length>230?'…':''),'tile-summary'));if(x.tags?.length){const tags=node('div',undefined,'tile-tags');x.tags.slice(0,4).forEach(t=>tags.append(node('span',t)));c.append(tags)}const bottom=node('div',undefined,'tile-bottom'),read=node('a',(x.collection==='video'?'打开视频档案':x.collection==='html'?'查看作品':'开始阅读')+' →');read.href=x.url;bottom.append(node('span',(x.trust&&!x.trust.startsWith('未标')?x.trust.split('（')[0]:'已归档').slice(0,18)),read);card.append(c,bottom);return card}));}\nasync function load(){ $('#retry').hidden=true;$('#count').textContent='正在加载内容…';$('#cards').setAttribute('aria-busy','true');try{const r=await fetch('/vault/catalog.json');if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data))throw Error();rows=data.sort((a,b)=>(b.date||'').localeCompare(a.date||'')||b.modified-a.modified);$('#total').replaceChildren(document.createTextNode(String(rows.length)),node('span','份知识成果'));filters();render()}catch(e){$('#count').textContent='暂时无法加载内容，请重试。';$('#retry').hidden=false}finally{$('#cards').setAttribute('aria-busy','false')}}\n$('#search').oninput=()=>{state();render()};$('#clear').onclick=()=>{selected='';$('#search').value='';state();filters();render();$('#search').focus()};$('#retry').onclick=load;load();\n"
CSS='\n/* UX pass 2026-10-11 */\n.vault-channel :is(a,button,input,select,textarea):focus-visible{outline:3px solid var(--v-accent);outline-offset:4px}\n.vault-home .channel-hero{padding-top:40px;padding-bottom:30px;gap:24px}\n.vault-home .channel-hero h1{font-size:clamp(36px,4vw,60px);line-height:1.3;margin:16px 0}\n.vault-home .channel-toolbar{align-items:center;gap:18px}.vault-home .channel-search{min-height:44px}\n.vault-home .channel-filters button{min-height:44px}.vault-home .tile-source{font-size:12px;color:var(--v-ink3);margin:8px 0}\n.vault-home .channel-meta{flex-wrap:wrap;gap:12px}.vault-home .ux-action{background:var(--v-bg2);border:1px solid var(--v-line);border-radius:8px;padding:10px 16px;color:var(--v-accent);cursor:pointer}\n.vault-channel [hidden]{display:none!important}.vault-channel .vn-links a{min-height:44px;display:inline-flex;align-items:center}\n#vault-versioned-docs .doc-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;padding:0;list-style:none}\n#vault-versioned-docs .doc-grid li{border:1px solid var(--v-line);padding:16px;border-radius:12px;background:var(--v-card)}\n#vault-versioned-docs .doc-grid a{display:block;font-weight:600;line-height:1.6}#vault-versioned-docs small{display:block;margin-top:8px;color:var(--v-ink3)}\n@media(max-width:700px){.vault-home .channel-hero{padding-top:24px}.vault-home .channel-toolbar{display:flex;flex-direction:column;align-items:stretch}.vault-home .channel-search{width:100%;order:-1}.vault-home .channel-filters{display:flex;flex-wrap:wrap}.vault-channel .vn-brand span{display:none}}\n@media(prefers-reduced-motion:reduce){.vault-channel *{scroll-behavior:auto!important;transition:none!important;animation:none!important}}\n'
def home(s):
 start=s.index('<script>')
 end=s.index('</script>',start)+len('</script>')
 s=s[:start]+'<script>'+JS+'</script>'+s[end:]
 s=s.replace('<span id="count" role="status">','<button id="clear" class="ux-action" type="button" hidden>清除筛选</button><button id="retry" class="ux-action" type="button" hidden>重新加载</button><span id="count" role="status" aria-live="polite">')
 return s
edit('src/agent_vault/web/channel.html',home)
edit('src/agent_vault/web/channel.css',lambda s:s+CSS if 'UX pass 2026-10-11' not in s else s)
print(str(backup))

PANEL='def panel():\n c=catalog()\n labels={\'vault-column-standards\': \'各栏目归档标准 · 从这里开始\', \'vault-maintain\': \'维护与发布档案\', \'vault-daily-brief\': \'生成每日简报\', \'reading-archive\': \'导入阅读资料\', \'book-press\': \'整理深度读书\', \'builders-digest\': \'整理建造者观察\', \'video-archive\': \'导入视频档案\', \'vault-readonly-mcp\': \'MCP 查询接口\', \'contract-v1\': \'通用输入契约\', \'production\': \'部署与运行\', \'reading-intelligence\': \'阅读分析与证据\', \'mimo-tts\': \'简报语音生成\', \'annotation-sdk-implementation\': \'划线与笔记 SDK\', \'video-import-contract\': \'视频来源与必填字段\', \'vault-column-schema\': \'栏目字段定义\'}\n parts=[\'<section id="vault-versioned-docs"><h2>技能与接口资料库</h2><p>先读栏目标准，再选择对应技能。配置连接请使用上方的复制按钮。</p><p>① 确定内容栏目 → ② 按标准准备材料 → ③ 接入 Agent 并校验结果</p><p>资料版本 \'+html.escape(c[\'version\'])+\' · \'+html.escape(c[\'updated\'])+\'</p>\']\n for kind,title in [(\'skill\',\'归档与创作技能\'),(\'mcp\',\'连接与接口\'),(\'reference\',\'字段、部署与参考说明\')]:\n  parts.append(\'<h3>\'+title+\'</h3><ul class="doc-grid">\')\n  for e in c[\'entries\']:\n   if e[\'type\']!=kind:continue\n   parts.append(\'<li><a href="/api/inside/vault/knowledge/integration-doc?id=\'+html.escape(e[\'id\'])+\'">\'+html.escape(labels.get(e[\'id\'],e[\'id\']))+\'</a><small>\'+html.escape(e[\'id\'])+\' · v\'+html.escape(e[\'version\'])+\'</small></li>\')\n  parts.append(\'</ul>\')\n return \'\'.join(parts)+\'<p>每份资料保留独立版本，更新记录与历史版本一并保存。</p></section>\'\n'
def docs(s):
 start=s.index('def panel():');end=s.index('def document(',start)
 return s[:start]+PANEL+'\n'+s[end:]
edit('src/agent_vault/integration_docs.py',docs)
